WITH base AS (SELECT * FROM accounts WHERE customer_id IN (4, 7, 22, 36) OR balance >= 40000), accounts_stats AS (SELECT CASE WHEN balance >= 71000 THEN 'high' WHEN balance >= 34000 THEN 'mid' ELSE 'low' END AS balance_bucket, account_type, SUM(balance) AS total_balance, COUNT(CASE WHEN status = 'FROZEN' THEN 1 END) AS frozen_count FROM base GROUP BY CASE WHEN balance >= 71000 THEN 'high' WHEN balance >= 34000 THEN 'mid' ELSE 'low' END, account_type) SELECT balance_bucket, account_type, total_balance, frozen_count FROM accounts_stats
